"""Audit real native sandwich fields and actual refinement; no solver rerun."""
from run_aircraft_a30 import *
from audit_aircraft_a05 import vtk
from assess_aircraft_a23_reader_precision import printed_bound
import inspect,subprocess

def preserve():
    import audit_aircraft_a27 as previous
    s=inspect.getsource(previous.preserve).replace('preservation_A27','preservation_A30');ns=dict(globals());exec(compile(s,__file__+'::preserve','exec'),ns);ns['preserve']();dump(OUT/'preservation_reader_derivation.json',{'source':rel(Path(previous.__file__)),'source_sha256':streamsha(Path(previous.__file__)),'derived_source':s,'old_files_only_read':True})

def review():
    guard();dest=OUT/'sandwich_qualification_review.json';assert not dest.exists();rows=read(OUT/'native_case_summary.json')['cases'];assert len(rows)==9;samples=[];cards=[];interfaces=[];plastic=[]
    for d in sorted((OUT/'w0').iterdir()):
        g=read(d/'generation.json');X=np.asarray(g['nodes_mm']);B=np.asarray(g['bricks']);pids=np.asarray(g['brick_parts']);n=g['name'];s=(d/(n+'_0000.rad')).read_text();checks={'source_core_card':'\n'.join(parent()['/MAT/LAW28/28'])+'\n' in s,'declared_skin_card':'\n'.join(skin.law12_card())+'\n' in s,'known_mass':abs(g['known_mass_g']-.2214)<1e-10,'native_frames':read(d/'native_frame_gate.json')['pass']};cards.append({'case':d.name,'checks':checks,'pass':all(checks.values())})
        sets={pid:set((B[pids==pid]-1).ravel()) for pid in [1,2,28]};lo=sets[1]&sets[28];hi=sets[2]&sets[28];expect=(g['mesh_n']+1)**2;checks={'lower_shared_face':len(lo)==expect and bool(np.all(X[list(lo),2]==-4)),'upper_shared_face':len(hi)==expect and bool(np.all(X[list(hi),2]==4)),'skins_no_shared_nodes':not bool(sets[1]&sets[2]),'no_duplicate_coordinates':len(np.unique(X,axis=0))==len(X)};interfaces.append({'case':d.name,'lower_shared_nodes':len(lo),'upper_shared_nodes':len(hi),'checks':checks,'pass':all(checks.values()),'physical_bond_is_hypothesis':True})
        H=histories(d/(n+'T01.csv'));pw={k:float(abs(v).max()*.001) for k,v in H.items() if k.startswith('SANDWICH_PARTS') and k.strip().endswith('PW')};plastic.append({'case':d.name,'native_part_PW_max_J':pw,'qualification':'Native diagnostic, no post-run elastic threshold or historical fracture claim'})
        native=sorted(p for p in d.glob(n+'A*') if re.fullmatch(re.escape(n)+r'A\d{3}',p.name));assert native
        for p in sorted(set([native[0],native[len(native)//2],native[-1]])):
            ad=OUT/'native_field_audit'/d.name;ad.mkdir(parents=True,exist_ok=True);v=ad/(p.name+'.vtk');assert not v.exists();res=subprocess.run([str(RUNTIME/'anim_to_vtk_win64.exe'),str(p)],capture_output=True,text=True,check=True,timeout=180);v.write_text(res.stdout,encoding='utf-8');q=vtk(res.stdout);order=np.argsort(q['NODE_ID']);pts=q['points'].reshape(-1,3)[order];disp=q['Displacement'].reshape(-1,3)[order];vel=q['Velocity'].reshape(-1,3)[order];bound=printed_bound(pts)+printed_bound(disp)+4*np.finfo(np.float32).eps*np.maximum.reduce([abs(pts),abs(disp),abs(X)])+1e-8;checks={'ids':bool(np.array_equal(q['NODE_ID'][order],np.arange(1,len(X)+1))),'finite':bool(np.isfinite(pts).all() and np.isfinite(disp).all() and np.isfinite(vel).all()),'identity_with_printing_bound':bool(np.all(abs(pts-X-disp)<=bound)),'no_eroded_elements':bool(np.all(q['EROSION_STATUS']==1))};samples.append({'case':d.name,'time_ms':q['time'],'native':rel(p),'native_sha256':streamsha(p),'vtk':rel(v),'vtk_sha256':streamsha(v),'checks':checks,'pass':all(checks.values())})
    dump(OUT/'native_fields_review.json',{'created_utc':now(),'samples':samples,'pass':all(x['pass'] for x in samples),'old_native_reruns':0,'printing_bound_not_physical_threshold':True});dump(OUT/'material_readback_review.json',{'created_utc':now(),'cases':cards,'pass':all(x['pass'] for x in cards)});dump(OUT/'shared_face_review.json',{'created_utc':now(),'cases':interfaces,'pass':all(x['pass'] for x in interfaces)});dump(OUT/'plastic_work_observation.json',{'created_utc':now(),'cases':plastic,'new_physical_failure_claim':False})
    h=dict(np.load(OUT/'w0/FREE_ROTATION_Y_N12/histories_SI.npz'));h2=dict(np.load(OUT/'w0/FREE_ROTATION_Y_N12_HALF/histories_SI.npz'));mask=(h['time_ms']>=h2['time_ms'][0])&(h['time_ms']<=h2['time_ms'][-1]);T=h['time_ms'][mask];ld=float(np.linalg.norm(h['physical_L_kg_m2_s'][mask]-np.column_stack([np.interp(T,h2['time_ms'],h2['physical_L_kg_m2_s'][:,a]) for a in range(3)]),axis=1).max());ed=float(abs(h['total_J'][mask]-np.interp(T,h2['time_ms'],h2['total_J'])).max());ratio=float(np.median(h2['time_step_ms'][1:])/np.median(h['time_step_ms'][1:]));dt={'actual_dt_ratio':ratio,'physical_L_difference_kg_m2_s':ld,'energy_difference_J':ed,'checks':{'actually_shorter':ratio<.6,'L_converges':bool(ld<.002*np.linalg.norm(h['physical_L_kg_m2_s'][0])+1e-9),'energy_converges':bool(ed<.002*h['total_J'][0]+1e-7)}};mesh=[]
    for motion in ['AFFINE_EXTENSION','CONSTRAINED_BENDING']:
        a=read(OUT/'w0'/f'{motion}_N6/review.json');b=read(OUT/'w0'/f'{motion}_N12/review.json');diff=abs(a['native_elastic_comparison_J']-b['native_elastic_comparison_J'])/b['native_elastic_comparison_J'];mesh.append({'motion':motion,'difference_fraction':diff,'pass':diff<.05,'N6':a,'N12':b})
    checks={'all_native_sets':all(x['pass'] for x in rows),'native_fields':all(x['pass'] for x in samples),'native_materials':all(x['pass'] for x in cards),'actual_shared_faces':all(x['pass'] for x in interfaces),'time_refinement':all(dt['checks'].values()),'spatial_refinement':all(x['pass'] for x in mesh)};dump(dest,{'created_utc':now(),'cases':rows,'refinement':dt,'mesh':mesh,'checks':checks,'sandwich_manufactured_scope_pass':all(checks.values()),'free_interior_transmission_qualified':False,'physical_debonding_or_fracture_qualified':False,'whole_insertion_ready':False,'objective1_complete':False});print({'A30_review':checks,'limited_scope_pass':all(checks.values())},flush=True)

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('action',choices=['preserve','review']);globals()[p.parse_args().action]()
